const puppeteer = require('puppeteer');
const fs = require('fs');
const path = require('path');

(async () => {
  const browser = await puppeteer.launch({
    headless: true,
    executablePath: '/root/.cache/puppeteer/chrome/linux-131.0.6778.204/chrome-linux64/chrome',
    args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-dev-shm-usage']
  });
  const page = await browser.newPage();
  await page.setViewport({ width: 1800, height: 1400, deviceScaleFactor: 2 });

  const htmlContent = fs.readFileSync('/app/chart.html', 'utf-8');
  await page.setContent(htmlContent, { waitUntil: 'networkidle0' });

  // Wait for any fonts/rendering
  await new Promise(r => setTimeout(r, 1000));

  await page.screenshot({
    path: '/app/output/result.png',
    fullPage: false,
    clip: { x: 0, y: 0, width: 1800, height: 1400 }
  });

  await browser.close();
  console.log('Saved to /app/output/result.png');
})();

