  }
</style>
</head>
<body>
<div class="container">
  <div class="title-block">
    <div class="title">The AI Timeline: Research Leads, Industry Follows, Regulation Catches Up</div>
    <div class="subtitle">Three parallel tracks of AI evolution (2010–2025) — with global private investment overlay. <em>ChatGPT compressed the multi-year lag between tracks to months.</em></div>
  </div>
  <div class="chart-area">
    <svg id="chart" width="1680" height="1240" viewBox="0 0 1680 1240"></svg>
  </div>
</div>

<script>
const data = {
  research: [
    {date: "2012-09", label: "AlexNet", significance: "high"},
    {date: "2014-06", label: "GANs", significance: "high"},
    {date: "2014-09", label: "Seq2Seq + Attention", significance: "medium"},
    {date: "2015-12", label: "ResNet", significance: "medium"},
    {date: "2016-03", label: "AlphaGo defeats Lee Sedol", significance: "critical"},
    {date: "2017-06", label: "Transformer", significance: "critical"},
    {date: "2018-06", label: "GPT-1", significance: "medium"},
    {date: "2018-10", label: "BERT", significance: "high"},
    {date: "2020-05", label: "GPT-3", significance: "critical"},
    {date: "2021-01", label: "DALL-E & CLIP", significance: "high"},
    {date: "2022-04", label: "PaLM", significance: "medium"},
    {date: "2023-03", label: "GPT-4", significance: "critical"},
    {date: "2024-02", label: "Gemini 1.5 (1M context)", significance: "high"},
    {date: "2024-09", label: "o1 reasoning model", significance: "high"},
    {date: "2025-02", label: "Claude 3.5 / GPT-4.5", significance: "high"}
  ],
  industry: [
    {date: "2011-10", label: "Siri launches", significance: "high"},
    {date: "2014-11", label: "Amazon Echo / Alexa", significance: "high"},
    {date: "2016-09", label: "Google Translate → NMT", significance: "medium"},
    {date: "2018-05", label: "Google Duplex", significance: "medium"},
    {date: "2020-06", label: "GPT-3 API", significance: "high"},
    {date: "2021-06", label: "GitHub Copilot", significance: "high"},
    {date: "2022-08", label: "Stable Diffusion", significance: "high"},
    {date: "2022-11", label: "ChatGPT", significance: "critical"},
    {date: "2023-02", label: "Bing + GPT-4", significance: "high"},
    {date: "2023-07", label: "Llama 2 open-sourced", significance: "high"},
    {date: "2024-01", label: "AI agents in enterprise", significance: "high"},
    {date: "2024-05", label: "GPT-4o multimodal", significance: "medium"},
    {date: "2025-01", label: "AI coding agents", significance: "high"}
  ],
  regulation: [
    {date: "2016-10", label: "Obama AI report", significance: "medium"},
    {date: "2018-04", label: "EU GDPR", significance: "high"},
    {date: "2019-04", label: "EU AI Ethics Guidelines", significance: "medium"},
    {date: "2020-02", label: "EU AI White Paper", significance: "medium"},
    {date: "2021-04", label: "EU AI Act proposed", significance: "high"},
    {date: "2022-10", label: "US AI Bill of Rights", significance: "medium"},
    {date: "2023-05", label: "EU AI Act agreed", significance: "critical"},
    {date: "2023-07", label: "WH voluntary commitments", significance: "high"},
    {date: "2023-10", label: "Biden Executive Order", significance: "critical"},
    {date: "2023-11", label: "Bletchley Declaration", significance: "high"},
    {date: "2024-03", label: "EU AI Act enacted", significance: "critical"},
    {date: "2024-11", label: "California SB 1047", significance: "high"},
    {date: "2025-02", label: "EU AI Act enforcement", significance: "high"}
  ],
  investment: [
    {year: 2010, investment: 1.3}, {year: 2011, investment: 1.9},
    {year: 2012, investment: 2.5}, {year: 2013, investment: 3.2},
    {year: 2014, investment: 5.5}, {year: 2015, investment: 8.5},
    {year: 2016, investment: 12.2}, {year: 2017, investment: 18.5},
    {year: 2018, investment: 28.4}, {year: 2019, investment: 32.1},
    {year: 2020, investment: 36.5}, {year: 2021, investment: 52.8},
    {year: 2022, investment: 48.2}, {year: 2023, investment: 67.2},
    {year: 2024, investment: 95.8}, {year: 2025, investment: 120.5}
  ]
};

const svg = document.getElementById('chart');
const W = 1680, H = 1240;
const LEFT = 140, RIGHT = 40, TOP = 30, BOTTOM = 80;
const chartW = W - LEFT - RIGHT;
const chartH = H - TOP - BOTTOM;

const minYear = 2010, maxYear = 2025.5;
function xScale(year) {
  return LEFT + ((year - minYear) / (maxYear - minYear)) * chartW;
}

function parseDate(d) {
  const [y, m] = d.split('-').map(Number);
  return y + (m - 1) / 12;
}

// Track layout
const trackColors = {
  research: { main: '#2563EB', light: '#DBEAFE', bg: '#EFF6FF', accent: '#1D4ED8' },
  industry: { main: '#059669', light: '#D1FAE5', bg: '#ECFDF5', accent: '#047857' },
  regulation: { main: '#DC2626', light: '#FEE2E2', bg: '#FEF2F2', accent: '#B91C1C' }
};

const trackLabels = { research: 'RESEARCH', industry: 'INDUSTRY', regulation: 'REGULATION' };

const trackY = {
  research: TOP + 60,
  industry: TOP + 340,
  regulation: TOP + 620
};
const trackH = 220;
const investmentTop = TOP + 880;
const investmentH = 260;

function el(tag, attrs, parent) {
  const e = document.createElementNS('http://www.w3.org/2000/svg', tag);
  for (const [k, v] of Object.entries(attrs || {})) e.setAttribute(k, v);
  if (parent) parent.appendChild(e);
  return e;
}

// Background fills for tracks
['research', 'industry', 'regulation'].forEach(track => {
  el('rect', {
    x: LEFT, y: trackY[track] - 10,
    width: chartW, height: trackH + 20,
    fill: trackColors[track].bg, rx: 6
  }, svg);
});

// Year grid lines
for (let y = 2010; y <= 2025; y++) {
  const x = xScale(y);
  el('line', {
    x1: x, y1: TOP + 45, x2: x, y2: investmentTop + investmentH,
    stroke: y % 5 === 0 ? '#ccc' : '#e5e5e5',
    'stroke-width': y % 5 === 0 ? 1 : 0.5,
    'stroke-dasharray': y % 5 === 0 ? 'none' : '3,3'
  }, svg);

  const label = el('text', {
    x: x, y: investmentTop + investmentH + 20,
    'text-anchor': 'middle',
    class: 'year-label'
  }, svg);
  label.textContent = y;
}

// ChatGPT vertical highlight
const chatgptX = xScale(2022 + 10/12);
el('rect', {
  x: chatgptX - 1.5, y: TOP + 40,
  width: 3, height: investmentTop + investmentH - TOP - 40,
  fill: '#F59E0B', opacity: 0.6, rx: 1
}, svg);

// Shaded acceleration zone (2022.8 to 2025)
el('rect', {
  x: chatgptX, y: TOP + 40,
  width: xScale(2025.3) - chatgptX,
  height: investmentTop + investmentH - TOP - 40,
  fill: '#FEF3C7', opacity: 0.3
}, svg);

// "ChatGPT" annotation
const cgAnnot = el('text', {
  x: chatgptX, y: TOP + 32,
  'text-anchor': 'middle',
  class: 'annotation-text',
  fill: '#B45309',
  'font-weight': '700',
  'font-size': '12px'
}, svg);
cgAnnot.textContent = '▼ ChatGPT (Nov 2022)';

// Track labels
['research', 'industry', 'regulation'].forEach(track => {
  const label = el('text', {
    x: LEFT - 16,
    y: trackY[track] + trackH / 2,
    'text-anchor': 'end',
    'dominant-baseline': 'middle',
    class: 'track-label',
    fill: trackColors[track].main,
    transform: `rotate(-90, ${LEFT - 16}, ${trackY[track] + trackH / 2})`
  }, svg);
  label.textContent = trackLabels[track];
});

// Horizontal track baseline
['research', 'industry', 'regulation'].forEach(track => {
  const baseY = trackY[track] + trackH / 2;
  el('line', {
    x1: LEFT, y1: baseY, x2: LEFT + chartW, y2: baseY,
    stroke: trackColors[track].main, 'stroke-width': 2, opacity: 0.3
  }, svg);
});

// Significance sizing
const sigRadius = { medium: 5, high: 7, critical: 10 };
const sigStroke = { medium: 1.5, high: 2, critical: 2.5 };

// Place milestones with collision avoidance
function placeMilestones(trackData, track) {
  const baseY = trackY[track] + trackH / 2;
  const items = trackData.map(d => ({
    ...d,
    x: xScale(parseDate(d.date)),
    r: sigRadius[d.significance]
  }));

  // Alternate labels above/below, with stagger for density
  const positions = [];
  items.forEach((item, i) => {
    let side = i % 2 === 0 ? -1 : 1; // -1 = above, 1 = below
    let offsetY = 28 + (item.significance === 'critical' ? 4 : 0);

    // Check for overlap with previous labels on same side
    const samesSide = positions.filter(p => p.side === side && Math.abs(p.x - item.x) < 85);
    if (samesSide.length > 0) {
      offsetY += samesSide.length * 16;
    }

    positions.push({ ...item, side, offsetY });
  });

  positions.forEach(item => {
    const cy = baseY;
    const labelY = cy + item.side * item.offsetY;

    // Connector line
    el('line', {
      x1: item.x, y1: cy + item.side * (item.r + 2),
      x2: item.x, y2: labelY + (item.side < 0 ? 6 : -8),
      stroke: trackColors[track].main, 'stroke-width': 0.8, opacity: 0.4,
      'stroke-dasharray': '2,2'
    }, svg);

    // Circle
    el('circle', {
      cx: item.x, cy: cy, r: item.r,
      fill: item.significance === 'critical' ? trackColors[track].main : trackColors[track].light,
      stroke: trackColors[track].main,
      'stroke-width': sigStroke[item.significance]
    }, svg);

    // Inner dot for critical
    if (item.significance === 'critical') {
      el('circle', {
        cx: item.x, cy: cy, r: 3,
        fill: '#fff'
      }, svg);
    }

    // Label
    const labelClass = item.significance === 'critical' ? 'milestone-label-critical' : 'milestone-label';
    const label = el('text', {
      x: item.x,
      y: labelY,
      'text-anchor': 'middle',
      class: labelClass,
      fill: item.significance === 'critical' ? trackColors[track].accent : '#444'
    }, svg);
    label.textContent = item.label;
  });
}

placeMilestones(data.research, 'research');
placeMilestones(data.industry, 'industry');
placeMilestones(data.regulation, 'regulation');

// Investment area chart
const invMaxVal = 130;
function invY(val) {
  return investmentTop + investmentH - (val / invMaxVal) * investmentH;
}

// Investment area fill
let areaPath = `M ${xScale(2010)} ${investmentTop + investmentH}`;
data.investment.forEach(d => {
  areaPath += ` L ${xScale(d.year)} ${invY(d.investment)}`;
});
areaPath += ` L ${xScale(2025)} ${investmentTop + investmentH} Z`;

// Gradient
const defs = el('defs', {}, svg);
const grad = el('linearGradient', { id: 'invGrad', x1: '0', y1: '0', x2: '0', y2: '1' }, defs);
el('stop', { offset: '0%', 'stop-color': '#8B5CF6', 'stop-opacity': '0.35' }, grad);
el('stop', { offset: '100%', 'stop-color': '#8B5CF6', 'stop-opacity': '0.05' }, grad);

el('path', { d: areaPath, fill: 'url(#invGrad)' }, svg);

// Investment line
let linePath = '';
data.investment.forEach((d, i) => {
  const prefix = i === 0 ? 'M' : ' L';
  linePath += `${prefix} ${xScale(d.year)} ${invY(d.investment)}`;
});
el('path', {
  d: linePath, fill: 'none',
  stroke: '#7C3AED', 'stroke-width': 2.5
}, svg);

// Investment dots and value labels for key years
const labelYears = [2010, 2014, 2017, 2020, 2022, 2023, 2024, 2025];
data.investment.forEach(d => {
  el('circle', {
    cx: xScale(d.year), cy: invY(d.investment), r: 3,
    fill: '#7C3AED', stroke: '#fff', 'stroke-width': 1.5
  }, svg);

  if (labelYears.includes(d.year)) {
    const label = el('text', {
      x: xScale(d.year),
      y: invY(d.investment) - 10,
      'text-anchor': 'middle',
      class: 'investment-label',
      fill: '#6D28D9'
    }, svg);
    label.textContent = `$${d.investment}B`;
  }
});

// Investment Y-axis labels
[0, 30, 60, 90, 120].forEach(v => {
  const y = invY(v);
  el('line', {
    x1: LEFT - 5, y1: y, x2: LEFT, y2: y,
    stroke: '#aaa', 'stroke-width': 1
  }, svg);
  const t = el('text', {
    x: LEFT - 10, y: y + 4,
    'text-anchor': 'end',
    class: 'axis-label'
  }, svg);
  t.textContent = `$${v}B`;
});

// Investment axis label
const invLabel = el('text', {
  x: LEFT - 50,
  y: investmentTop + investmentH / 2,
  'text-anchor': 'middle',
  class: 'track-label',
  fill: '#7C3AED',
  transform: `rotate(-90, ${LEFT - 50}, ${investmentTop + investmentH / 2})`
}, svg);
invLabel.textContent = 'INVESTMENT';

// Lag annotation arrows
