const sigRadius = { medium: 4.5, high: 6, critical: 9 };
const sigStroke = { medium: 1.5, high: 1.8, critical: 2.5 };

function multilineText(parent, x, y, text, attrs) {
  const lines = text.split('\n');
  const lineH = 12;
  const startY = y - ((lines.length - 1) * lineH) / 2;
  lines.forEach((line, i) => {
    const t = el('text', {
      x: x, y: startY + i * lineH,
      ...attrs
    }, parent);
    t.textContent = line;
  });
}

function placeMilestones(trackData, track) {
  const baseY = trackY[track] + trackH / 2;
  const items = trackData.map(d => ({
    ...d,
    x: xScale(parseDate(d.date)),
    r: sigRadius[d.significance],
    numLines: d.label.split('\n').length
  }));

  // Smart label placement: alternate above/below, push away from collisions
  const placed = []; // {x, y, w, h, side}

  items.forEach((item, i) => {
    // Try above first for even, below for odd
    let preferredSide = i % 2 === 0 ? -1 : 1;
    let bestSide = preferredSide;
    let bestOffset = 26 + (item.significance === 'critical' ? 4 : 0);
    const labelH = item.numLines * 12 + 4;
    const approxW = item.label.split('\n').reduce((max, l) => Math.max(max, l.length * 6.5), 0);

    // Check collisions and find best offset
    for (let attempt = 0; attempt < 4; attempt++) {
      const side = attempt < 2 ? preferredSide : -preferredSide;
      let offset = 26 + (item.significance === 'critical' ? 4 : 0) + (attempt % 2) * 18;

      const labelCenterY = baseY + side * offset;
      const labelTop = labelCenterY - labelH / 2;
      const labelBot = labelCenterY + labelH / 2;
      const labelLeft = item.x - approxW / 2;
      const labelRight = item.x + approxW / 2;

      let collision = false;
      for (const p of placed) {
        if (labelRight > p.x - p.w/2 - 4 && labelLeft < p.x + p.w/2 + 4 &&
            labelBot > p.y - p.h/2 - 2 && labelTop < p.y + p.h/2 + 2) {
          collision = true;
          break;
        }
      }

      if (!collision) {
        bestSide = side;
        bestOffset = offset;
        break;
      }

      // If all attempts collide, push further
      if (attempt === 3) {
        bestSide = side;
        bestOffset = offset + 16;
      }
    }

    const labelY = baseY + bestSide * bestOffset;
    placed.push({ x: item.x, y: labelY, w: approxW, h: labelH, side: bestSide });

    // Connector line
    const connStart = baseY + bestSide * (item.r + 2);
    const connEnd = labelY + (bestSide < 0 ? labelH/2 + 1 : -labelH/2 - 1);
    el('line', {
      x1: item.x, y1: connStart, x2: item.x, y2: connEnd,
      stroke: trackColors[track].main, 'stroke-width': 0.7, opacity: 0.35,
      'stroke-dasharray': '2,2'
    }, svg);

    // Circle
    el('circle', {
      cx: item.x, cy: baseY, r: item.r,
      fill: item.significance === 'critical' ? trackColors[track].main : trackColors[track].light,
      stroke: trackColors[track].main,
      'stroke-width': sigStroke[item.significance]
    }, svg);

    if (item.significance === 'critical') {
      el('circle', { cx: item.x, cy: baseY, r: 3, fill: '#fff' }, svg);
    }

    // Label
    const isCrit = item.significance === 'critical';
    multilineText(svg, item.x, labelY, item.label, {
      'text-anchor': 'middle',
      'font-family': FF,
      'font-size': isCrit ? '11px' : '10px',
      'font-weight': isCrit ? '700' : '500',
      fill: isCrit ? trackColors[track].accent : '#444'
    });
  });
}

